using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class ModelDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Exact low-bit packet heights", H("Two rows and two positivity charts"),
        Blocks(Paragraph(Text("With x=8tzw and y=2qx, the rational model uses the original four heads and their exact enlarged-source heads. Its four-by-four mask array is [u,z/2-1,q-1,D0], [3w/8-u-1,0,0,D1], [w/8,0,3q,x/2-2-D0-D1], [0,0,y/2-4q,1], where D0=t(w+3z+2) and D1=tzw. Terminal order is U,X,W,V. qPeak accumulates these physical masses and terminals, starting at zero in the old row and A in the new row. qExpr is either the post-terminal seam or the upper-strip cap minus the pre-terminal peak. The two charts substitute z=4 or z=Z+8, w=4z(V+1), t=T+1 and q=R+1, with u=2(V+1)-1 or 2(V+1)."))), []));
}
